using Aptiverse.Api.Data.Abstractions;
using Microsoft.EntityFrameworkCore;

namespace Aptiverse.Affiliates.Domain.Models
{
    public enum PayoutStatus
    {
        // Generated by a payout run, waiting for the founder to pay it from
        // his banking app and come back with the reference.
        Draft,
        // Money has left his account. PaymentReference is what his bank
        // statement will show.
        Paid,
        // Abandoned before payment. The entries are released back to Payable.
        Cancelled,
    }

    // One payment the founder makes to one affiliate.
    //
    // Nothing in this system moves money. This row is the accounting record of
    // a transfer he made himself, in his own banking app, and typed the
    // reference back in. That is the whole design: the software does the
    // arithmetic and the paperwork, a human does the payment.
    //
    // The banking fields are SNAPSHOTS taken at generation time rather than a
    // join to the affiliate. If someone changes their bank account in
    // February, the payout made in November must still say where the money
    // actually went.
    [Index(nameof(AffiliateId))]
    [Index(nameof(Status))]
    [Index(nameof(PaidAt))]
    [Index(nameof(RunReference))]
    public class AffiliatePayout : IEntityTimestamps
    {
        public long Id { get; set; }
        public long AffiliateId { get; set; }

        // Groups every payout produced by one run, so the founder can pull up
        // "the October list" as a unit.
        public required string RunReference { get; set; }

        // The window of commission this payout settles. PeriodStart is the day
        // after the previous run's end for this affiliate, or the first entry
        // if there was none.
        public DateTime PeriodStart { get; set; }
        public DateTime PeriodEnd { get; set; }

        [Precision(18, 2)]
        public decimal TotalZar { get; set; }

        public int EntryCount { get; set; }

        public PayoutStatus Status { get; set; } = PayoutStatus.Draft;

        // What he typed into his banking app. The single field that lets a
        // bank statement line be matched to this ledger entry in five years.
        public string? PaymentReference { get; set; }
        public DateTime? PaidAt { get; set; }
        public string? PaidByUserId { get; set; }
        public string? Notes { get; set; }

        // ---- Snapshot of who was paid and where, at generation time --------
        public string? PayeeName { get; set; }
        public string? PayeeIdType { get; set; }
        public string? PayeeIdNumber { get; set; }
        public string? PayeeTaxReferenceNumber { get; set; }
        public string? BankName { get; set; }
        public string? AccountHolderName { get; set; }
        public string? AccountNumber { get; set; }
        public string? BranchCode { get; set; }
        public string? AccountType { get; set; }

        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
        public DateTime UpdatedAt { get; set; } = DateTime.UtcNow;

        public virtual Affiliate? Affiliate { get; set; }
        public virtual ICollection<AffiliatePayoutItem> Items { get; set; } = [];
    }
}
